// checks: expSyms=108 expRng=35628 frameType=1 refMode=1 skipPresent=true

void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  test(
    'HarborInterFrameWalk: COMPOUND (REFERENCE_MODE_SELECT) frame sync vs SW',
    () async {
      const expSyms = 108, expRng = 35628;
      const maxBytes = 24;
      const txCoeffSizes = [0, 1, 2, 3];
      const ms = HarborInterFrameWalk.maxSyms;
      const nctx = HarborInterFrameWalk.numCtx;

      final t = HarborInterFrameWalk(
        maxBytes: maxBytes,
        txCoeffSizes: txCoeffSizes,
      );
      final clk = SimpleClockGenerator(10).clk;
      final reset = Logic(name: 'reset');
      final start = Logic(name: 'start');
      final bytes = Logic(name: 'bytes', width: maxBytes * 8);
      final allowHp = Logic(name: 'allow_hp');
      final forceInt = Logic(name: 'force_int');
      final txModeSel = Logic(name: 'tx_mode_select');
      final skipModePresent = Logic(name: 'skip_mode_present');
      final refModeSelect = Logic(name: 'ref_mode_select');
      final skipRef0 = Logic(name: 'skip_ref0', width: 3);
      final skipRef1 = Logic(name: 'skip_ref1', width: 3);
      final signBias = Logic(name: 'sign_bias', width: 8);
      final maskedEn = Logic(name: 'enable_masked_compound');
      final mmSwitch = Logic(name: 'mm_switchable');
      final allowWarp = Logic(name: 'allow_warped_motion');
      final cdfIn = Logic(name: 'cdf_in', width: nctx * ms * 16);
      final nsymsIn = Logic(name: 'nsyms_in', width: nctx * 5);

      void conn(String p, Logic s) => t.input(p).srcConnection! <= s;
      conn('clk', clk);
      conn('reset', reset);
      conn('start', start);
      conn('bytes', bytes);
      conn('allow_hp', allowHp);
      conn('force_integer_mv', forceInt);
      conn('tx_mode_select', txModeSel);
      conn('skip_mode_present', skipModePresent);
      conn('ref_mode_select', refModeSelect);
      conn('skip_ref0', skipRef0);
      conn('skip_ref1', skipRef1);
      conn('sign_bias', signBias);
      conn('enable_masked_compound', maskedEn);
      conn('mm_switchable', mmSwitch);
      conn('allow_warped_motion', allowWarp);
      final enableII = Logic(name: 'enable_interintra');
      conn('enable_interintra', enableII);
      conn('cdf_in', cdfIn);
      conn('nsyms_in', nsymsIn);
      await t.build();

      reset.inject(1);
      start.inject(0);
      bytes.inject(_bytesPk);
      allowHp.inject(_allowHp);
      forceInt.inject(_forceInt);
      txModeSel.inject(_txModeSel);
      skipModePresent.inject(_skipModePresent);
      refModeSelect.inject(_refModeSelect);
      skipRef0.inject(_skipRef0);
      skipRef1.inject(_skipRef1);
      signBias.inject(_signBias);
      maskedEn.inject(1);
      mmSwitch.inject(_mmSwitch);
      allowWarp.inject(_allowWarp);
      enableII.inject(0);
      cdfIn.inject(_cdfPk);
      nsymsIn.inject(_nsymsPk);

      Simulator.setMaxSimTime(400000000);
      unawaited(Simulator.run());
      await clk.nextPosedge;
      reset.inject(0);
      await clk.nextPosedge;
      start.inject(1);
      await clk.nextPosedge;
      start.inject(0);

      int sgn16(int v) => v >= 0x8000 ? v - 0x10000 : v;

      final hwRng = <int>[];
      final hwBlocks = <List<int>>[];
      var guard = 0;
      while (true) {
        final doneV = t.output('done').value;
        if (doneV.isValid && doneV.toInt() == 1) break;
        if (!doneV.isValid) {
          // ignore: avoid_print
          print('done went X at guard=$guard after ${hwRng.length} symbols');
          break;
        }
        await clk.nextPosedge;
        final sv = t.output('sym_valid').value;
        if (sv.isValid && sv.toInt() == 1) {
          final rv = t.output('rng').value;
          hwRng.add(rv.isValid ? rv.toInt() : -1);
        }
        final bv = t.output('block_valid').value;
        if (bv.isValid && bv.toInt() == 1) {
          hwBlocks.add([
            t.output('blk_r').value.toInt(),
            t.output('blk_c').value.toInt(),
            t.output('blk_bs').value.toInt(),
            t.output('blk_mode').value.toInt(),
            t.output('blk_ref0').value.toInt(),
            sgn16(t.output('blk_mvrow').value.toInt()),
            sgn16(t.output('blk_mvcol').value.toInt()),
            t.output('blk_modectx').value.toInt(),
            t.output('blk_count').value.toInt(),
            t.output('blk_ref1').value.toInt(),
            sgn16(t.output('blk_mvrow1').value.toInt()),
            sgn16(t.output('blk_mvcol1').value.toInt()),
            t.output('blk_comptype').value.toInt(),
            t.output('blk_skipmode').value.toInt(),
          ]);
        }
        if (++guard > 200000) fail('compound frame decode timeout');
      }

      var firstDiff = -1;
      final nCmp = hwRng.length < _goldRng.length
          ? hwRng.length
          : _goldRng.length;
      for (var i = 0; i < nCmp; i++) {
        if (hwRng[i] != _goldRng[i]) {
          firstDiff = i;
          break;
        }
      }
      if (firstDiff >= 0) {
        // ignore: avoid_print
        print(
          'FIRST DIVERGENCE at symbol $firstDiff: '
          'HW rng=${hwRng[firstDiff]} SW rng=${_goldRng[firstDiff]}',
        );
      }
      // ignore: avoid_print
      print(
        'HW decoded ${hwRng.length} symbols; SW ${_goldRng.length}. '
        'In-sync through symbol ${firstDiff < 0 ? nCmp - 1 : firstDiff - 1}.',
      );

      expect(firstDiff, equals(-1), reason: 'every od_ec symbol matches SW');
      expect(
        hwRng.length,
        equals(expSyms),
        reason: 'HW decodes all $expSyms symbols',
      );
      expect(
        hwRng.last,
        equals(expRng),
        reason: 'frame-end od_ec rng == $expRng',
      );

      // Leaf-level: every block matches SW (incl. the compound block's ref pair,
      // 2 MVs, comp type, skip_mode).
      final sw0 = _swBlocks;
      expect(
        hwBlocks.length,
        equals(sw0.length),
        reason: 'HW decodes all ${sw0.length} inter blocks',
      );
      var sawCompound = false;
      for (var i = 0; i < sw0.length; i++) {
        final g = sw0[i];
        final b = hwBlocks[i];
        expect(
          [b[0], b[1], b[2]],
          equals([g[0], g[1], g[2]]),
          reason: 'block $i position/size',
        );
        expect(b[3], equals(g[5]), reason: 'block $i inter_mode');
        expect(b[4], equals(g[4]), reason: 'block $i ref0');
        expect([b[5], b[6]], equals([g[7], g[8]]), reason: 'block $i MV0');
        expect(b[7], equals(g[9]), reason: 'block $i mode_context');
        expect(b[8], equals(g[10]), reason: 'block $i refMvCount');
        // Compound fields (SW interBlockTrace appended: ref1, mvR1, mvC1, compType).
        final swRef1 = g[20]; // -1 for single-ref
        if (swRef1 >= 1) {
          sawCompound = true;
          expect(b[9], equals(swRef1), reason: 'block $i ref1');
          expect(
            [b[10], b[11]],
            equals([g[21], g[22]]),
            reason: 'block $i MV1',
          );
          expect(b[12], equals(g[23]), reason: 'block $i compType');
          expect(b[13], equals(1), reason: 'block $i skip_mode');
        } else {
          expect(b[9], equals(0), reason: 'block $i single-ref (ref1 == 0)');
          expect(b[13], equals(0), reason: 'block $i not skip_mode');
        }
      }
      expect(
        sawCompound,
        isTrue,
        reason: 'the frame contains a compound block',
      );

      await Simulator.endSimulation();
    },
  );
}
